Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Notation zlen l := (Z.of_nat (length l)).

Definition X2PATH (L : Z) (h : hstats) (maxW : Z) (rs0a : list Z) (nz : Z) (rs0d : list Z) (sorted : list (option Z))
    (rv0 rv : list Z) (cells : list (option deltX2)) : Prop :=
  let ws := hs_weights h in let rank := hs_rank h in let nbS := hs_nbSymbols h in let tl := hs_tableLog h in
  let T := (if (tl <=? 11) && (11 <? L) then 11 else L) in
  let rs0c := Zupd (maxW + 1 + 1) nz (Zupd (0 + 1) nz rs0a) in
  let rs0 := Zupd (0 + 1) 0 rs0d in
  let mB := tl + 1 - maxW in
  find_maxW (S (Z.to_nat tl)) tl rank = Ok maxW /\ 1 <= maxW <= tl
  /\ rank_start2 (Z.to_nat maxW) 1 0 rank (repeat 0 15) = Ok (rs0a, nz)
  /\ sort2 (Z.to_nat nbS) 0 ws rs0c (repeat None 256) = Ok (rs0d, sorted)
  /\ rank_val0 (Z.to_nat maxW) 1 0 (T - tl - 1) rank (repeat 0 (12 * 13)) = Ok rv0
  /\ rank_val_rows (Z.to_nat (Z.max 0 (T - mB + 1 - mB))) mB maxW rv0 = Ok rv
  /\ fill_x2 (Z.to_nat (maxW + 1)) (repeat None (Z.to_nat (2 ^ L))) 1 (maxW + 1) T rv sorted rs0 (tl + 1) = Ok cells
  /\ 1 <= tl <= 12 /\ tl <= T <= 12 /\ T <= L /\ zlen ws = nbS /\ 2 <= nbS <= 256 /\ length rank = 13%nat
  /\ (forall i, 0 <= i < 13 -> 0 <= Znth i rank <= 256) /\ (forall i, 0 <= i < nbS -> 0 <= Znth i ws <= 12)
  /\ length rs0a = 15%nat /\ (forall i, 0 <= i < 15 -> 0 <= Znth i rs0c <= 256)
  /\ length rs0d = 15%nat /\ length sorted = 256%nat /\ (forall i v, nth i sorted None = Some v -> 0 <= v < 256)
  /\ length rv0 = 156%nat /\ length rv = 156%nat
  /\ (forall j, 1 <= j < maxW + 1 -> 0 <= Znth j rv0 < 2^31)
  /\ (forall w, 1 <= w <= maxW -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256)
  /\ (forall w, 1 <= w <= maxW ->
        0 <= Znth w rv /\ Znth w rv + 2 ^ (T - (tl + 1 - w)) * (Znth (w + 1) rs0 - Znth w rs0) <= 4096)
  /\ (forall c w2, mB <= c <= T - mB -> 1 <= w2 <= maxW -> 0 <= Znth (rv_idx c w2) rv < 2^31)
  /\ x2_table_ok (x2_cells cells) T /\ zlen cells = 2 ^ L
  /\ (forall i, 0 <= i < 2 ^ T -> exists c, nth (Z.to_nat i) cells None = Some c).

